PROMPTS = json.loads(r'''[{"id": "fleurs001", "source": "fleurs", "origin": "", "voice": "anitha", "text": "அக்டோபரில் தொடங்கப்பட்ட பரவலான ஆட்சி எதிர்ப்பு போராட்டங்களுக்கு, இந்த ஆணையம்தான் மார்ட்டெல்லியின் பதிலுரை."}, {"id": "fleurs002", "source": "fleurs", "origin": "", "voice": "arun", "text": "அதன் பலனாக, நடிகர்களும் கூட மேடையின் மீது கஞ்சாவை புகைக்கிறார்கள், மற்றும் தியேட்டரும் கூட பார்வையாளர்களை அதில் இணைய உற்சாகப்படுத்துகிறது."}, {"id": "fleurs003", "source": "fleurs", "origin": "", "voice": "anitha", "text": "அதே மாதத்தில் மஷ்ஹட்டில் வேறு ஒரு விமானம், ரன்வேயைத் தாண்டி ஓடி ஒரு சுவற்றில் மூட்டியதில் பதினேழு பேர் கொல்லப் பட்டார்கள்."}, {"id": "fleurs004", "source": "fleurs", "origin": "", "voice": "arun", "text": "அந்த நகரம், நாட்டின் மற்ற நகரங்களிலிருந்து முற்றிலும் மாறுபட்டது, ஏனெனில் அது ஆப்பிரிக்க சுவையன்றி அராபியச் சுவை கொண்டிருக்கிறது."}, {"id": "fleurs005", "source": "fleurs", "origin": "", "voice": "anitha", "text": "அனைத்து தென்னாப்பிரிக்க தேசிய பூங்காக்களைப் போலவே, அங்கு தினசரி பாதுகாப்பு மற்றும் நுழைவு கட்டணங்கள் உள்ளன."}, {"id": "fleurs006", "source": "fleurs", "origin": "", "voice": "arun", "text": "அவர் ஆரம்பத்தில் கிரேட் யார்மவுத்தில் உள்ள ஜேம்ஸ் பேஜெட் மருத்துவமனையில் அனுமதிக்கப்பட்டார்."}, {"id": "fleurs007", "source": "fleurs", "origin": "", "voice": "anitha", "text": "அவற்றுக்குச் செதில்கள் மற்றும் நகங்களைக் கொண்ட கால்கள் உள்ளன, அவை முட்டையிடுகின்றன, மேலும் அவை டி-ரெக்ஸ் போன்ற இரண்டு பின்புற கால்களிலும் நடக்கின்றன."}, {"id": "fleurs008", "source": "fleurs", "origin": "", "voice": "arun", "text": "ஆனால் அது உண்மை அல்ல. அந்த ஆவணத்தின் பின்பகுதியில் ஏதோ எழுதப் பட்டிருந்தாலும், அது புதையலுக்கான வரைபடம் இல்லை."}, {"id": "fleurs009", "source": "fleurs", "origin": "", "voice": "anitha", "text": "ஆனால், பறவைகளில் டைனோசரைப் போல தோற்றமளிக்கும் பல விஷயங்கள் இன்னமும் இருக்கின்றன."}, {"id": "fleurs010", "source": "fleurs", "origin": "", "voice": "arun", "text": "ஆளும் கட்சியான சௌத் வெஸ்ட் ஆஃப்ரிக்கா பீபிள்ஸ் ஆர்கனைசேஷன் (ஸ்வேபோ) பாராளுமன்ற தேர்தலில் தனது பெரும்பான்மையை தக்க வைத்துக் கொண்டது."}, {"id": "fleurs011", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இணையதளத்தில் விரோத சூழல் பயிற்சி குறித்தான தேடலானது, ஒரு உள்ளுர் நிறுவனத்தின் முகவரியை பெரும்பாலும் வழங்கும்."}, {"id": "fleurs012", "source": "fleurs", "origin": "", "voice": "arun", "text": "இணையம் மக்கள் தொடர்பு மற்றும் தனிநபர்கள் தொடர்புகொள்வதற்கான கூறுகளை ஒருங்கிணைக்கிறது."}, {"id": "fleurs013", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இது எங்களுக்கு ரயில், கார் மற்றும் பல போக்குவரத்து சாதனங்களைக் கொண்டு வந்து சேர்த்துள்ளது."}, {"id": "fleurs014", "source": "fleurs", "origin": "", "voice": "arun", "text": "இது தண்ணீருக்குள் நுழையும் எதையும் தாக்கியது; டி. ரெக்ஸ் போன்ற ஒரு பெரிய டைனோசர் கூட அதன் அளவுடன் நெருங்கமுடியாது."}, {"id": "fleurs015", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இது விவேகமானதாகத் தோன்றுகிறது, ஏனென்றால் பூமி நகர்வதைப் போல உணரவில்லை, இல்லையா?"}, {"id": "fleurs016", "source": "fleurs", "origin": "", "voice": "arun", "text": "இந்த அறிவிப்பு ட்ரம்ப், துருக்கியின் ஜனாதிபதி ரெஸெப் டய்யிப் ஏர்டோகனுடன் நடத்திய தொலைபேசி உரையாடலின் பின்னர் செய்யப்பட்டது."}, {"id": "fleurs017", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இந்த எதிர்ப்புகள் வெடித்தவுடன், பிரிட்டன் ஜெர்மனி மீது ஒரு கடற்படை முற்றுகையை ஆரம்பித்தது."}, {"id": "fleurs018", "source": "fleurs", "origin": "", "voice": "arun", "text": "இந்த ஜோடிகள், அவர்களுக்கான குழந்தையை தத்தெடுக்க திட்டங்களை தேர்வு செய்கிறார்கள்."}, {"id": "fleurs019", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இந்த நகரம் ஆப்ரிக்காவில் உள்ள சில மலிவான மலை கொரில்லா கண்காணிப்புடன் சேர்ந்து, நைரகோங்கோ எரிமலையை ஏறுவதற்கான தளமாகவும் இருக்கிறது."}, {"id": "fleurs020", "source": "fleurs", "origin": "", "voice": "arun", "text": "இந்த நோய் பன்றிகளால் கொண்டு வரப்பட்டது, பிறகு அது கொசுக்கள் மூலம் மனிதர்களுக்கு பரவுகிறது."}, {"id": "fleurs021", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இந்த வதந்திகளை அர்த்தமற்ற அரசியல் பேச்சு மற்றும் முட்டாள்தனம் என்று அவர் குறிப்பிட்டார்."}, {"id": "fleurs022", "source": "fleurs", "origin": "", "voice": "arun", "text": "இன்று, தங்கள் இறக்கைகளை மடிக்க முடியாத ஒரே பூச்சிகள் தும்பித் தட்டான் மற்றும் மேஃப்ளைகள் ஆகும்."}, {"id": "fleurs023", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இயற்கையான சூழல் தாவரங்களுக்கு மிகவும் சிறப்பானவையாகும், ஆகவே ஒரே ஒரு மாதிரியை கூட நீக்குவதற்கான சோதனையை எதிர்க்கவும்."}, {"id": "fleurs024", "source": "fleurs", "origin": "", "voice": "arun", "text": "இரண்டு தலைமுறைகளுக்கு இடையே பாகுபாடானது பிரித்தல் மற்றும் மறுசீரமைப்பு செய்தல் மூலம் முன்னும் பின்னுமாக கலந்து மாறுபாடு செய்கிறது."}, {"id": "fleurs025", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இரண்டு வயதுவந்த குழந்தைகளுடன் திருமணம் செய்து கொண்ட டுவல்லால், இக்கதை விவரிக்கப்பட்ட மில்லரின் மனதில் ஒரு பெரிய அபிப்ராயத்தை ஏற்படுத்த முடியவில்லை."}, {"id": "fleurs026", "source": "fleurs", "origin": "", "voice": "arun", "text": "இரண்டே வாரங்களில் அமெரிக்கப் படைகளும் சுதந்திர பிரெஞ்சு படைகளும் தெற்கு பிரான்ஸை விடுவித்து ஜெர்மனியை நோக்கி திரும்பின."}, {"id": "fleurs027", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இருக்கும் எல்லா வளங்களையும் ஒரு நிறுவனத்தின் எல்லா துறைகளும் சிறப்பாக பயன்படுத்தினால் படைப்பாற்றல் மற்றும் புத்திசாலித்தனம் அனைவருக்கும் பயன்படும்."}, {"id": "fleurs028", "source": "fleurs", "origin": "", "voice": "arun", "text": "இறுதியாக, பல சிறிய பூனைகள் (வீட்டில் வளர்க்கப்படும் பூனைகளும் சேர்த்து) பல வகையான சிறிய வகை பூச்சிகள், எலிகள், பல்லிகள் மற்றும் பறவைகளை உண்கின்றன."}, {"id": "fleurs029", "source": "fleurs", "origin": "", "voice": "anitha", "text": "இவை சில நேரங்களில் கரையோரத்தில் வரிசையாக உள்ள கடைகளுடன் கூடிய நீச்சல் பாதுகாப்பான நெரிசலான குடும்ப கடற்கரைகளாகும்."}, {"id": "fleurs030", "source": "fleurs", "origin": "", "voice": "arun", "text": "இவ்வாறு, பென்சில் தயாரித்து வெளிவந்த காலத்தில் பல மக்களுக்கு ஒரு நல்ல நண்பராக இருந்தது."}, {"id": "fleurs031", "source": "fleurs", "origin": "", "voice": "anitha", "text": "உங்களுக்கு ரோமானிய மொழி தெரிந்தால், போர்ச்சிகிசியம் கற்றுக்கொள்வது சுலபமாக இருக்கும் என்பதை சொல்ல தேவையில்லை."}, {"id": "fleurs032", "source": "fleurs", "origin": "", "voice": "arun", "text": "உண்மையில், அது இருப்பதை ஒருவர் அறிந்திருந்தாலும் அதைக் கண்டுபிடிப்பது எளிதல்ல. குகைக்குள் ஒருமுறை சென்றால், அது மொத்த தனிப்படுத்தல் ஆகும்."}, {"id": "fleurs033", "source": "fleurs", "origin": "", "voice": "anitha", "text": "உலர்ந்த இரண்டு பொடிகளையும் ஒன்றாக கலந்து பின்பு அதனை சுத்தமான ஈர கைகளால் கசக்கி உருண்டை பிடிக்கவும்."}, {"id": "fleurs034", "source": "fleurs", "origin": "", "voice": "arun", "text": "எனவே, இக்குறியிடல் வெறுமனே ஒரு லேபிளாகச் சேர்க்கப்பட்டிருக்கலாம்."}, {"id": "fleurs035", "source": "fleurs", "origin": "", "voice": "anitha", "text": "எனினும், அதிகாரிகளிடம் அறிவுரை பெற்று, அறிவுறுத்தல்களை மதித்து நடந்து, பாதுகாப்பு தொடர்பான எச்சரிக்கைகளுக்குக் கூடுதல் கவனம் செலுத்துங்கள்."}, {"id": "fleurs036", "source": "fleurs", "origin": "", "voice": "arun", "text": "எப்படியாக இருப்பினும், ஷெங்கன் மண்டலம் இந்த விஷயத்தில் ஒரு நாட்டைப் போலவே செயல்படுகிறது."}, {"id": "fleurs037", "source": "fleurs", "origin": "", "voice": "anitha", "text": "ஏரோஸ்மித், அவர்களின் சுற்றுப்பயணத்தில் மீதமுள்ள இசை நிகழ்ச்சிகளை ரத்து செய்தார்."}, {"id": "fleurs038", "source": "fleurs", "origin": "", "voice": "arun", "text": "ஐரோப்பிய வரலாற்றின் இந்த காலகட்டத்தில், பணம் பொருந்தியதாகவும், சக்திவாய்ந்ததாகவும் மாறிய கத்தோலிக்க திருச்சபை ஆய்வுக்கு உட்படுத்தப்பட்டது."}, {"id": "fleurs039", "source": "fleurs", "origin": "", "voice": "anitha", "text": "ஒரு சமூகமாக குறிப்பிடத்தக்க ஒரு பெரிய மக்கள் கூட்டம் ஒற்றுமையுடன் வேலை செய்து, இணைந்து வாழும் ஒற்றை கலாச்சாரமே நாகரீகமாகும்."}, {"id": "fleurs040", "source": "fleurs", "origin": "", "voice": "arun", "text": "ஒரு வெடிகுண்டு, ஆளுனர் அதிகாரி அலுவலகத்தின் வெளியே வெடித்தது."}, {"id": "fleurs041", "source": "fleurs", "origin": "", "voice": "anitha", "text": "கண்டுபிடிப்பானது பறவைகளில் இறகுகளின் பரிணாம வளர்ச்சியைப் பற்றிய நுண்ணறிவை வழங்குகிறது."}, {"id": "fleurs042", "source": "fleurs", "origin": "", "voice": "arun", "text": "கறி என்பது இறைச்சி அல்லது காய்கறிகளுடன், மூலிகைகள் மற்றும் மசாலாப் பொருட்களை அடிப்படையாகக் கொண்ட ஒரு உணவாகும்."}, {"id": "fleurs043", "source": "fleurs", "origin": "", "voice": "anitha", "text": "கழிவறை தேவைப்பட்ட மூதாட்டியின் இடத்தை புகைப்படக் கலைஞர்கள் எடுத்துக்கொண்டனர். மெண்டோசா சுட்டுக் கொல்லப்பட்டார்."}, {"id": "fleurs044", "source": "fleurs", "origin": "", "voice": "arun", "text": "காட்சிகள் பிரமிடுகளில் காட்சிப்படுத்தப்பட்டு வெவ்வேறு பிரமிடுகள் ஒளியேற்றப்படும்."}, {"id": "fleurs045", "source": "fleurs", "origin": "", "voice": "anitha", "text": "காட்டுக் குழந்தைகள் அவர்கள் கைவிடப்படுவதற்கு அல்லது ஓடிப்போவதற்கு முன் கடுமையான துஷ்பிரயோகங்களையோ அல்லது அதிர்ச்சியையோ அனுபவித்திருக்கலாம்."}, {"id": "fleurs046", "source": "fleurs", "origin": "", "voice": "arun", "text": "காணொலி விளையாட்டுகளில் விளையாட்டுக் கருவியை காற்றில் நகர்த்துவதன் மூலம், விளையாட்டு வீரர்களால் செயல்களையும் இயக்கங்களையும் கட்டுப்படுத்த இயலும்."}, {"id": "fleurs047", "source": "fleurs", "origin": "", "voice": "anitha", "text": "கால்சியம் மற்றும் பொட்டாசியம் போன்ற தனிமங்கள் உலோகங்களாக கருதப்படுகின்றன. நிச்சயமாக, தங்கம் வெள்ளி போன்ற உலோகங்களும் அதில் உள்ளன."}, {"id": "fleurs048", "source": "fleurs", "origin": "", "voice": "arun", "text": "காவல்துறை மேற்பார்வையாளர் சந்திர ஷேகர சோலங்கி குற்றம் சாட்டப்பட்டவர்கள் நீதிமன்றத்தில் முகத்தை மூடியவாறு தோன்றினர்."}, {"id": "fleurs049", "source": "fleurs", "origin": "", "voice": "anitha", "text": "கிராஃபிட்டி கட்டமைப்புகளில் குறிப்பதன் மூலமாகவோ அல்லது கீருவதன் மூலமாகவோ தளத்தின் அழகை கெடுக்க வேண்டாம்."}, {"id": "fleurs050", "source": "fleurs", "origin": "", "voice": "arun", "text": "கிரேக்க மொழி அறிவு குறைந்து வருவதால், மேற்குப் பகுதி அதன் கிரேக்க தத்துவ மற்றும் விஞ்ஞான வேர்களிலிருந்து துண்டிக்கப்பட்டதாக உணர்கிறது."}, {"id": "fleurs051", "source": "fleurs", "origin": "", "voice": "anitha", "text": "குறிப்பாக, ஒரு நபரின் மைக்ரோ- உணர்ச்சிகளின் உட்பொருளை சரியாக விளக்குவதன் மூலம் அவர் பொய் சொல்கிறாரா என்பதை கண்டறிய இயலும் என்று கூறப்படுகிறது."}, {"id": "fleurs052", "source": "fleurs", "origin": "", "voice": "arun", "text": "குறைந்த மன இறுக்கம், அதிக நேர்மறை வாழ்க்கையைக் கொடுக்கும் ஒவ்வொரு மனிதரிடமும் முழுமையான அமைதி மற்றும் திருப்தியைக் காணும் திறன் உள்ளது."}, {"id": "fleurs053", "source": "fleurs", "origin": "", "voice": "anitha", "text": "குறைப்புகளுக்கு ஒரு புள்ளிவிவரத்தை அவர் அமைக்கவில்லை, அவை சீனாவின் பொருளாதார உற்பத்தியின் அடிப்படையில் செய்யப்படும் என்று அவர் கூறினார்."}, {"id": "fleurs054", "source": "fleurs", "origin": "", "voice": "arun", "text": "கோட்பாட்டை அடிப்படையாகக் கொண்ட வேலைகள் மட்டுமே பெரும்பாலும் முடிக்கப்பட்டுள்ளன. ஆனால் இந்த திட்டம் தனுசு விண்மீனை கண்காணிக்க துண்டுதலாக எழுதப்பட்டது."}, {"id": "fleurs055", "source": "fleurs", "origin": "", "voice": "anitha", "text": "கோயத், ஃபிக்டே மற்றும் ஸ்க்லீகல் போன்ற எழுத்தாளர்களிடமிருந்து பெறப்பட்ட கலாச்சார உறுதிக்கான மிகப் பெரிய அம்சம் ரொமான்டிசிஸத்தில் இருந்தது."}, {"id": "fleurs056", "source": "fleurs", "origin": "", "voice": "arun", "text": "சந்திரனின் மேற்பரப்பு பாறைகள் மற்றும் தூசுகளால் ஆனது. சந்திரனின் வெளிப்புற அடுக்கு க்ரஸ்ட் என்று அழைக்கப்படுகிறது."}, {"id": "fleurs057", "source": "fleurs", "origin": "", "voice": "anitha", "text": "சந்திரன் பூமியில் ஒரு இழுவை செலுத்தி அலைகளை ஏற்படுத்துகிறது, அதே போல் பால்வீதி, தனுசு விண்மீன் கூட்டம் மீது ஒரு சக்தியை செலுத்துகிறது."}, {"id": "fleurs058", "source": "fleurs", "origin": "", "voice": "arun", "text": "சிங்கங்களின் குழு என்பது ஒன்று முதல் மூன்று வரையிலான பெரிய ஆண் சிங்கங்களுடன், முப்பது பெண் சிங்கங்களும், குட்டிகளும் கொண்டதாகும்."}, {"id": "fleurs059", "source": "fleurs", "origin": "", "voice": "anitha", "text": "சிங்கங்களில் சமூக பூனைகள், பிரைடுகள் என்றழைக்கப்படும் பெரிய குழுக்களில் வாழ்கின்றன."}, {"id": "fleurs060", "source": "fleurs", "origin": "", "voice": "arun", "text": "சிறிய தீவுகளில் பெரும்பாலானவை தனி தேசங்களாக அல்லது பிரான்சுடன் தொடர்புடையவையாக இருந்தன, அவை ஆடம்பர கடற்கரை உல்லாச விடுதிகள் என அழைக்கப்படுகின்றன."}, {"id": "fleurs061", "source": "fleurs", "origin": "", "voice": "anitha", "text": "சில அணுகளில் நிலையில்லாத அணுக்கரு உள்ளது. அதாவது, அவை சிறிது இடித்தால் அல்லது இடிக்காமலே பிளந்து கொள்ளலாம்."}, {"id": "fleurs062", "source": "fleurs", "origin": "", "voice": "arun", "text": "சில பகுதிகளில் நீர் கொதிக்க ஒரு நிமிடம் போதுமானதாக உள்ளது, மற்ற இடங்களில் பல நிமிடங்கள் தேவைப்படுகின்றன."}, {"id": "fleurs063", "source": "fleurs", "origin": "", "voice": "anitha", "text": "சில வினைச்சொற்கள் மற்றும் ஆப்ஜெக்ட் எனப்படும் வாக்கிய பகுதியை வேறுபடுத்துவதற்கு இது ஒரு முக்கியமான வழியாகும்."}, {"id": "fleurs064", "source": "fleurs", "origin": "", "voice": "arun", "text": "ஜப்பானின் அணுசக்தி முகவாண்மையின்படி ஆலையில், கதிரியக்க சீசியம் மற்றும் அயோடின் கண்டறியப்பட்டுள்ளது."}, {"id": "fleurs065", "source": "fleurs", "origin": "", "voice": "anitha", "text": "ஜியான்கார்லோ ஃபிஷிசெல்லா தனது காரின் கட்டுப்பாட்டை இழந்தார் மற்றும் தொடங்கிய பிறகு மிக விரைவிலேயே பந்தயத்தை அவர் முடித்துவிட்டார்."}, {"id": "fleurs066", "source": "fleurs", "origin": "", "voice": "arun", "text": "தீவுக்கூட்டங்களிலும் ஏரிகளிலும் படகுகள் அவசியமானதல்ல."}, {"id": "fleurs067", "source": "fleurs", "origin": "", "voice": "anitha", "text": "துணி மிகவும் வெப்பமடைதலை அனுமதிக்காதபடி கவனமாக இருக்கவும் (அதனால் துணி சுருங்கலாம் அல்லது தீவிர நிகழ்வுகளில் துணி தீயில் வாட்டப்படலாம்)."}, {"id": "fleurs068", "source": "fleurs", "origin": "", "voice": "arun", "text": "தொலைக்காட்சி அறிக்கைகள் ஆலையிலிருந்து வெண்ணிறப் புகை வெளிவருவதை காண்பித்தன."}, {"id": "fleurs069", "source": "fleurs", "origin": "", "voice": "anitha", "text": "நாட்டில் எந்தச் சேதமும் ஏற்படவில்லை என்று வடக்கு மரியானாஸ் அவசரநிலை மேலாண்மை அலுவலகம் தெரிவித்துள்ளது."}, {"id": "fleurs070", "source": "fleurs", "origin": "", "voice": "arun", "text": "நிறைய மக்கள் தங்களை டைனோஸர்ஸ் என்று நினைப்பதில்லை ஏனெனில் அவற்றிற்கு இறகுகள் உள்ளன மற்றும் அவைகளால் பறக்க முடியும்."}, {"id": "fleurs071", "source": "fleurs", "origin": "", "voice": "anitha", "text": "நீங்கள் உங்கள் சொந்த கருத்தைத் தவிர அரசாங்கங்களின் ஆலோசனையை பெற விரும்பலாம், ஆனால் அவர்களின் ஆலோசனை அவர்களின் குடிமக்களுக்கென உருவாக்கப்பட்டுள்ளது."}, {"id": "fleurs072", "source": "fleurs", "origin": "", "voice": "arun", "text": "நீங்கள் செயல்பாட்டுடன் நெருக்கமாக இருக்க விரும்பினால், இசைக்கு நெருக்கமான ஒரு முகாம் தளத்தைப் பெறுவதற்கு நீங்கள் சீக்கிரம் செல்ல வேண்டும்."}, {"id": "fleurs073", "source": "fleurs", "origin": "", "voice": "anitha", "text": "நீங்கள் ஷிப்போர்ட் எக்ஸ்கிரஷன்ஸைப் பயன்படுத்தி கரைக்கு சென்றால் உங்களுக்கு தனி விசா அவசியமில்லை."}, {"id": "fleurs074", "source": "fleurs", "origin": "", "voice": "arun", "text": "நேஷ்னல் டிரஷர் திரைப்படத்தை நீங்கள் பார்த்திருந்தால், சுதந்திரப் பிரகடனத்தின் பின்புறத்தில் ஒரு புதையல் வரைபடம் எழுதப்பட்டதாக நீங்கள் நினைக்கலாம்."}, {"id": "fleurs075", "source": "fleurs", "origin": "", "voice": "anitha", "text": "பக் என்ற சொல், இந்தப் பூச்சிக் குழுவுக்கான முறையான பொருளில் பூச்சியியல் வல்லுநர்களால் பயன்படுத்தப்படுகிறது."}, {"id": "fleurs076", "source": "fleurs", "origin": "", "voice": "arun", "text": "பின்னர் அவர் கேம்பிரிட்ஜில் உள்ள ஏட்டன்ப்ரூக் மருத்துவமனைக்கு மாற்றப்பட்டார்."}, {"id": "fleurs077", "source": "fleurs", "origin": "", "voice": "anitha", "text": "பின்லாந்து ஒரு சிறந்த படகு போக்குவரத்து இடமாகும். ஆயிரம் ஏரிகளின் நாடு ஆயிரக்கணக்கான தீவுகள் ஏரிகள் மற்றும் கடலோர தீவுகூடங்களை கொண்டுள்ளது."}, {"id": "fleurs078", "source": "fleurs", "origin": "", "voice": "arun", "text": "பிரபஞ்சத்தில் உள்ள அனைத்தும் பருப்பொருட்களால் ஆனவை. அனைத்து பருப்பொருட்களும் அணுக்கள் எனப்படும் சிறிய துகள்களால் ஆனவை."}, {"id": "fleurs079", "source": "fleurs", "origin": "", "voice": "anitha", "text": "பிரமிட் ஒலி மற்றும் ஒளி நிகழ்ச்சி ஆகியவை, இந்தப் பகுதியில் குழந்தைகளுக்கு மிக சுவாரஸ்யமான விஷயங்களில் ஒன்றாகும்."}, {"id": "fleurs080", "source": "fleurs", "origin": "", "voice": "arun", "text": "பிராந்திய மற்றும் பருவகாலங்களின் கடுமையான வானிலை நிகழ்வுகளில் பனி மழை, பனிப்புயல், ஆலங்கட்டி புயல் மற்றும் தூசு புயல்கள் ஆகியவையும் அடங்கும்."}, {"id": "fleurs081", "source": "fleurs", "origin": "", "voice": "anitha", "text": "பிலிப்பினே புகைப்படக் கலைஞர்களைப் போலவே ஆறு பணயக்கைதிகள், குழந்தைகள் மற்றும் முதியவர்கள் முதலில் விடுவிக்கப்பட்டனர்."}, {"id": "fleurs082", "source": "fleurs", "origin": "", "voice": "arun", "text": "புதன் கிழமை நிகழ்வுக்குப் பின்னர் கார்பெண்டோ பந்தயத்தில், இரு தனிப்பட்ட பந்தயங்களில் போட்டியிட்டார்."}, {"id": "fleurs083", "source": "fleurs", "origin": "", "voice": "anitha", "text": "புதிதாக ஒரு விஷயம் வரும்போது, கீபோர்டு என்ன மாயங்களைச் செய்யும் என்று ஒருவர் சிந்திக்க முடியும்."}, {"id": "fleurs084", "source": "fleurs", "origin": "", "voice": "arun", "text": "புனரமைப்பு முயற்சியின் தாராளவாத விமர்சனம், வாஷிங்டன் மக்களுக்குப் புணரமைப்பு ஒப்பந்தங்களை வழங்குவதில் கவனம் செலுத்தியுள்ளது."}, {"id": "fleurs085", "source": "fleurs", "origin": "", "voice": "anitha", "text": "புரட்சிக்குப் பிறகு எல்லாத் தொழில்களும் எல்லா ஆண் விண்ணப்ப தாரர்களுக்குமாக, மிகவும் ஆர்வமும், வெற்றிகரமாகவும் இருந்தவர்கள் முன்னேற வகை செய்தது."}, {"id": "fleurs086", "source": "fleurs", "origin": "", "voice": "arun", "text": "புரட்சிப் போரின் போது, பதின்மூன்று மாநிலங்கள்- காங்கிரசை மட்டுமே கொண்ட - ஒரு பலமில்லாத மத்திய அரசை கூட்டமைப்பு வரையறையின் கீழ் உருவாக்கின."}, {"id": "fleurs087", "source": "fleurs", "origin": "", "voice": "anitha", "text": "புலியின் உறுமல், சிங்கத்தின் பெரிய கர்ஜனை போன்றதல்ல, கத்திப் பேசும் வார்த்தைகள் கொண்ட உறுமலான சொற்றொடர் போன்றது."}, {"id": "fleurs088", "source": "fleurs", "origin": "", "voice": "arun", "text": "பெண்கள்: எந்தவொரு பெண் பயணியும் அசல் திருமண நிலையைப் பொருட்படுத்தாமல் தாங்கள் திருமணமானவர்களாகக் கூறப்படுவது பரிந்துரைக்கப்படுகிறது."}, {"id": "fleurs089", "source": "fleurs", "origin": "", "voice": "anitha", "text": "பெரும்பாலான நவீன ஆராய்ச்சி தொலைநோக்கிகள், தொலைதூரப் பகுதிகளில் மகத்தான வசதிகளுடன், சாதகமான வளிமண்டல நிலைகளைக் கொண்டுள்ளன."}, {"id": "fleurs090", "source": "fleurs", "origin": "", "voice": "arun", "text": "பெல்ஜியன் தரநிலையை ஒத்திருக்கிறது ஹாட் சாக்லேட்டுகள். பழச்சாறுகளின் விலை அதிகமாக உள்ளது, ஆனால் சிறப்பாக உள்ளது."}, {"id": "fleurs091", "source": "fleurs", "origin": "", "voice": "anitha", "text": "பொழுதுபோக்கு கைவினைகள், தொலைநிலை தரவு மற்றும் குரல் தேவைகள் கொண்ட சுற்றுப்பயணங்கள் உள்ளிட்ட கப்பலால் சேவை அடிக்கடி பயன்படுத்தபடுகிறது."}, {"id": "fleurs092", "source": "fleurs", "origin": "", "voice": "arun", "text": "போர் முடிந்து இரண்டு ஆண்டுகளுக்கு பிறகு, முன்னாள் கூட்டாளிகள் இப்போது எதிரிகளாக மாறினர் மற்றும் பனிப்போர் தொடங்கியது."}, {"id": "fleurs093", "source": "fleurs", "origin": "", "voice": "anitha", "text": "மக்கள் இப்போது செய்திகளை கணிணித் திரையில் எழுதுகிறார்கள், எழுதுவதற்கு அவர்கள் பென்சில் சீவிகளின் அருகில் வரப்போவதில்லை."}, {"id": "fleurs094", "source": "fleurs", "origin": "", "voice": "arun", "text": "மடகாஸ்கர் மிகப்பெரியது, வனவிலங்குகளுக்கென்று வரும் நிலையில், இது ஒரு தனிக்கண்டமாக கருதப்படுகிறது."}, {"id": "fleurs095", "source": "fleurs", "origin": "", "voice": "anitha", "text": "மத்திய கிழக்கின் வெதுவெதுப்பான காலநிலையில், வீடு அவ்வளவு முக்கியத்துவம் வாய்ந்ததாக இல்லை."}, {"id": "fleurs096", "source": "fleurs", "origin": "", "voice": "arun", "text": "மறுபுறம், பனிக்கட்டி மற்றும் பனிப்பொழிவு நிலைமை பல நாடுகளில் இயல்பானது, மேலும் அங்கு ஆண்டு முழுவதும் போக்குவரத்து தடையின்றியே இருக்கிறது."}, {"id": "fleurs097", "source": "fleurs", "origin": "", "voice": "anitha", "text": "மலைகளில் உயரமான இடத்தில் இந்த விபத்து நிகழ்ந்ததாகவும், இது பகைவர்கள் வைத்த தீயாக இருக்கலாம் என்றும் நம்பப்படுகிறது."}, {"id": "fleurs098", "source": "fleurs", "origin": "", "voice": "arun", "text": "மல்டோவாவின் தலைநகர் கிஷினோவ். உள்ளூர் மொழி ரோமானியன், ஆனால் பெரும்பாலும் ரஷ்ய மொழியே பயன்படுத்தப்படுகிறது."}, {"id": "fleurs099", "source": "fleurs", "origin": "", "voice": "anitha", "text": "மிக அதிக வரியுடைய நாடுகளுக்குச் செல்லும் பயணிகள் சில சமயங்களில் முக்கியமாக மதுபானங்கள் மற்றும் புகையிலையில் குறிப்பிடத்தக்க அளவு பணத்தை சேமிக்கலாம்."}, {"id": "fleurs100", "source": "fleurs", "origin": "", "voice": "arun", "text": "மிடில் ஆர்டர் பேட்ஸ்மேன்களான சச்சின் டெண்டுல்கர், ராகுல் டிராவிட் ஆகியோர் சிறப்பாக செயல்பட்டு கூட்டாக நூறு ரன்கள் எடுத்தனர்."}, {"id": "fleurs101", "source": "fleurs", "origin": "", "voice": "anitha", "text": "முக்கியமான மேடைகளில் இசை நிகழ்ச்சி முடிந்திருந்தாலும், விழாவின் சில பிரிவுகள் இரவு இசைப்பதைத் தொடரும்."}, {"id": "fleurs102", "source": "fleurs", "origin": "", "voice": "arun", "text": "முட்டைகோஸ் தனது சாறின் நிறத்தை எவ்வளவு அமிலத்தன்மை அல்லது காரத்தை பொறுத்து மாற்றுகிது."}, {"id": "fleurs103", "source": "fleurs", "origin": "", "voice": "anitha", "text": "மூளை நோயியல் மற்றும் நடத்தைக்கு இடையிலான தொடர்பு விஞ்ஞானிகள் ஆராய்ச்சிக்கு உதவுகிறது."}, {"id": "fleurs104", "source": "fleurs", "origin": "", "voice": "arun", "text": "மெய்நிகர் அணிகள் வழக்கமான அணிகளைப் போலவே சிறந்து விளங்குகின்றன, ஆனால் சில நுட்பமான வேறுபாடுகள் உள்ளன."}, {"id": "fleurs105", "source": "fleurs", "origin": "", "voice": "anitha", "text": "மேல் ஓடு மெல்லியதாக இருப்பதால், அருகிலுள்ள பக்கத்தில் அதிகமான மரியா இருக்கலாம். எரிமலைக்குழம்பு மேற்பரப்பு வரை உயர்வதற்கு எளிதாக இருந்தது."}, {"id": "fleurs106", "source": "fleurs", "origin": "", "voice": "arun", "text": "ரிப் கரண்ட்கள் என்பவை, பெரும்பாலும், பாறை உள்ள இடங்கள் அல்லது அது போன்ற இடங்களில், கடற்கரையிலிருந்து வரும் அலைகளின் எதிர் ஓட்டமாகும்."}, {"id": "fleurs107", "source": "fleurs", "origin": "", "voice": "anitha", "text": "ரோம் நகரில் பல இடங்களில் ஏராளமான பெரிய தொலைக்காட்சித் திரைகள் அமைக்கப்பட்டு, மக்கள் இந்த விழாவைக் காண முடிந்தது."}, {"id": "fleurs108", "source": "fleurs", "origin": "", "voice": "arun", "text": "ரோஸ்பி எண் குறைவாக உள்ள நட்சத்திரம், காந்தப்புற மாற்ற தொடர்புகளுடன் மிகவும் குறைந்த செயல்பாடு கொண்டதாகவே இருக்கும்."}, {"id": "fleurs109", "source": "fleurs", "origin": "", "voice": "anitha", "text": "லக்கா சிங் பஜனையை வழங்கினார். பாடகர், ராஜு கண்டெல்வலும் அவருடன் வந்திருந்தார்."}, {"id": "fleurs110", "source": "fleurs", "origin": "", "voice": "arun", "text": "லத்தீன் மொழியை பெரும்பாலும் மதச் சடங்குகளில் பயன்படுத்தினாலும் இத்தாலியன் மொழியும் அந்த நாட்டில் வேலை செய்யும் மக்கள் தினசரி பயன்படுத்தும் மொழியாகும்."}, {"id": "fleurs111", "source": "fleurs", "origin": "", "voice": "anitha", "text": "லூனாவுக்குச் சக மல்யுத்த வீரர்களும் அஞ்சலி செலுத்தினர்."}, {"id": "fleurs112", "source": "fleurs", "origin": "", "voice": "arun", "text": "வடக்கில் இன்னும் கூடுதல் தூரத்தில் உள்ள பெரும் பகுதிகள் மிக அதிக மக்கள் தொகை கொண்டவை. சில கிட்டத்தட்ட மக்களே வசிக்காத வனாந்தரமாக உள்ளது."}, {"id": "fleurs113", "source": "fleurs", "origin": "", "voice": "anitha", "text": "வடக்கே உலக புகழ்பெற்ற மரியன் மாய தோற்றங்களின் இடமான நம்முடைய லேடி ஆஃப் ஃபாத்திமாவின் (கோவில்) பெரிய தெய்வ இல்லத்தைப் பார்வையிடவும்."}, {"id": "fleurs114", "source": "fleurs", "origin": "", "voice": "arun", "text": "வனவிலங்குகளின் வாழ்விடமாக விளங்கும் மணல் பட்டைகள் மற்றும் கடற்கரைகளை உருவாக்க இந்த வண்டல் அவசியம்."}, {"id": "fleurs115", "source": "fleurs", "origin": "", "voice": "anitha", "text": "வழக்கமாக நீங்கள் எப்போதும் இங்கே சுற்றுலா பயணிகள் மற்றும் விற்பனையாளர்களின் ஒலியை கேட்கலாம். ஒலி மற்றும் ஒளியின் கதையானது ஒரு கதை புத்தகம் போன்றது."}, {"id": "fleurs116", "source": "fleurs", "origin": "", "voice": "arun", "text": "வீட்டிற்கு திரும்பும் பயணிகளுக்கு பொறுமையும் புரிந்துகொள்ளுதலும் மிகவும் அவசியம் என்று மக்கள் எதிர்பார்க்க கூடாது."}, {"id": "fleurs117", "source": "fleurs", "origin": "", "voice": "anitha", "text": "ஸ்பிரிங்போக்ஸைப் பொறுத்தவரை, அது ஐந்து போட்டிகளில் தோல்வியடைந்தது."}, {"id": "fleurs118", "source": "fleurs", "origin": "", "voice": "arun", "text": "ஹாங்காங்கின் சிறப்பான காட்சிகளைப் பார்ப்பதற்கு, தீவை விட்டு வெளியேறி காவ்லூன் நீர்நிலைக்கு செல்லுங்கள்."}, {"id": "fleurs119", "source": "fleurs", "origin": "", "voice": "anitha", "text": "ஹைகிங் பாதையைப் போன்ற பனிச்சறுக்கு பாதையைப் பற்றிச் சிந்தியுங்கள்."}, {"id": "fleurs120", "source": "fleurs", "origin": "", "voice": "arun", "text": "’அவர்களது வளர்ச்சி நிலை, பொறுப்பு மற்றும் திறன்களை மீறிய கடமைகளை ஏற்றுக்கொள்ளுமாறு அவர்களை நீங்கள் கேட்க கூடாது’ என்று அவர் மேலும் கூறினார்."}, {"id": "dir001", "source": "dir", "origin": "c01", "voice": "anitha", "text": "நாளைக்கு காலையில ஒரு மீட்டிங் இருக்கு."}, {"id": "dir002", "source": "dir", "origin": "c02", "voice": "arun", "text": "அந்த புத்தகம் மேஜை மேல இருக்கு."}, {"id": "dir003", "source": "dir", "origin": "c03", "voice": "anitha", "text": "பஸ் ஸ்டாப் இந்த தெருவுல கடைசியில இருக்கு."}, {"id": "dir004", "source": "dir", "origin": "c04", "voice": "arun", "text": "நான் நாளைக்கு சென்னைக்கு போறேன்."}, {"id": "dir005", "source": "dir", "origin": "c05", "voice": "anitha", "text": "இந்த கடை காலையில ஒன்பது மணிக்கு திறக்கும்."}, {"id": "dir006", "source": "dir", "origin": "c06", "voice": "arun", "text": "அவங்க ரெண்டு வருஷம் அங்க வேலை செஞ்சாங்க."}, {"id": "dir007", "source": "dir", "origin": "c07", "voice": "anitha", "text": "மழை நேத்து ராத்திரி நின்னுடுச்சு."}, {"id": "dir008", "source": "dir", "origin": "c08", "voice": "arun", "text": "இந்த ஃபைல்ல மூணு பேஜ் இருக்கு."}, {"id": "dir009", "source": "dir", "origin": "c09", "voice": "anitha", "text": "அவன் வீட்டுக்கு நடந்தே போனான்."}, {"id": "dir010", "source": "dir", "origin": "c10", "voice": "arun", "text": "டிக்கெட் ஆன்லைன்ல புக் பண்ணலாம்."}, {"id": "dir011", "source": "dir", "origin": "c11", "voice": "anitha", "text": "அந்த படம் ரெண்டு மணி நேரம் ஓடும்."}, {"id": "dir012", "source": "dir", "origin": "c12", "voice": "arun", "text": "சாவி டேபிள் டிராவர்ல இருக்கு."}, {"id": "dir013", "source": "dir", "origin": "c13", "voice": "anitha", "text": "இன்னைக்கு வியாழக்கிழமை."}, {"id": "dir014", "source": "dir", "origin": "c14", "voice": "arun", "text": "அவங்க வீடு ஸ்கூல் பக்கத்துல இருக்கு."}, {"id": "dir015", "source": "dir", "origin": "c15", "voice": "anitha", "text": "நாளைக்கு ரிசல்ட் வரும்."}, {"id": "dir016", "source": "dir", "origin": "c16", "voice": "arun", "text": "இந்த ரோட்டுல லைட் இல்ல."}, {"id": "dir017", "source": "dir", "origin": "c17", "voice": "anitha", "text": "அவன் காலையில ஒரு டம்ளர் பால் குடிப்பான்."}, {"id": "dir018", "source": "dir", "origin": "c18", "voice": "arun", "text": "கூட்டம் நாலு மணிக்கு ஆரம்பிக்கும்."}, {"id": "dir019", "source": "dir", "origin": "c19", "voice": "anitha", "text": "அந்த நம்பர் எனக்கு தெரியும்."}, {"id": "dir020", "source": "dir", "origin": "c20", "voice": "arun", "text": "இது ரெண்டாவது மாடி."}, {"id": "dir021", "source": "dir", "origin": "c21", "voice": "anitha", "text": "அவங்க அப்பா ஒரு டீச்சர்."}, {"id": "dir022", "source": "dir", "origin": "c22", "voice": "arun", "text": "நான் அந்த மெயில் அனுப்பிட்டேன்."}, {"id": "dir023", "source": "dir", "origin": "c23", "voice": "anitha", "text": "இந்த வாரம் லீவ் இல்ல."}, {"id": "dir024", "source": "dir", "origin": "c24", "voice": "arun", "text": "கார் வெளியில நிக்குது."}, {"id": "dir025", "source": "dir", "origin": "c25", "voice": "anitha", "text": "அவன் பேரு ராஜா."}, {"id": "dir026", "source": "dir", "origin": "c26", "voice": "arun", "text": "இந்த ஃபோன் நம்பர் மாறிடுச்சு."}, {"id": "dir027", "source": "dir", "origin": "c27", "voice": "anitha", "text": "நாங்க அங்க ஒரு வாரம் இருந்தோம்."}, {"id": "dir028", "source": "dir", "origin": "c28", "voice": "arun", "text": "அந்த ஆஃபீஸ் ஞாயிற்றுக்கிழமை மூடியிருக்கும்."}, {"id": "dir029", "source": "dir", "origin": "c29", "voice": "anitha", "text": "டீ டேபிள் மேல இருக்கு."}, {"id": "dir030", "source": "dir", "origin": "c30", "voice": "arun", "text": "இந்த ட்ரெயின் பத்து நிமிஷம் லேட்."}, {"id": "dir031", "source": "dir", "origin": "c31", "voice": "anitha", "text": "அவங்க நேத்து வந்தாங்க."}, {"id": "dir032", "source": "dir", "origin": "c32", "voice": "arun", "text": "இந்த வேலை நாளைக்கு முடியும்."}, {"id": "dir033", "source": "dir", "origin": "c33", "voice": "anitha", "text": "அந்த பெட்டி கனமா இருக்கு."}, {"id": "dir034", "source": "dir", "origin": "c34", "voice": "arun", "text": "நான் அந்த ஃபார்ம் ஃபில் பண்ணிட்டேன்."}, {"id": "dir035", "source": "dir", "origin": "c35", "voice": "anitha", "text": "இந்த ஏரியால நெட்வொர்க் கம்மியா இருக்கு."}, {"id": "dir036", "source": "dir", "origin": "c36", "voice": "arun", "text": "அவன் பஸ்ல வந்தான்."}, {"id": "dir037", "source": "dir", "origin": "c37", "voice": "anitha", "text": "இந்த மாசம் முப்பது நாள் இருக்கு."}, {"id": "dir038", "source": "dir", "origin": "c38", "voice": "arun", "text": "அந்த கடைக்காரர் காலையில வருவாரு."}, {"id": "dir039", "source": "dir", "origin": "c39", "voice": "anitha", "text": "நாளைக்கு எனக்கு ஒரு அப்பாயின்ட்மென்ட் இருக்கு."}, {"id": "dir040", "source": "dir", "origin": "c40", "voice": "arun", "text": "இந்த லிஸ்ட்ல அவங்க பேரு இல்ல."}, {"id": "dir041", "source": "dir", "origin": "e01", "voice": "anitha", "text": "ரொம்ப வருஷம் கழிச்சு உன்னை பார்க்கறேன், எப்படி இருக்க?"}, {"id": "dir042", "source": "dir", "origin": "e02", "voice": "arun", "text": "நான் ரொம்ப நாளா இதுக்காக காத்துட்டு இருந்தேன், கடைசியா ஆயிடுச்சு!"}, {"id": "dir043", "source": "dir", "origin": "e03", "voice": "anitha", "text": "அவங்களுக்கு வேலை கிடைச்சுடுச்சு, வீட்ல எல்லாரும் சந்தோஷமா இருக்காங்க."}, {"id": "dir044", "source": "dir", "origin": "e04", "voice": "arun", "text": "என் பொண்ணு ஃபர்ஸ்ட் மார்க் எடுத்துருக்கா."}, {"id": "dir045", "source": "dir", "origin": "e05", "voice": "anitha", "text": "இன்னைக்கு என் வாழ்க்கையில ரொம்ப நல்ல நாள்."}, {"id": "dir046", "source": "dir", "origin": "e06", "voice": "arun", "text": "நீ வந்துட்ட, இப்ப எல்லாம் சரியாகிடும்."}, {"id": "dir047", "source": "dir", "origin": "e07", "voice": "anitha", "text": "எனக்கு இப்ப ரொம்ப நிம்மதியா இருக்கு."}, {"id": "dir048", "source": "dir", "origin": "e08", "voice": "arun", "text": "இந்த செய்தி கேட்டு எனக்கு அழுகையே வந்துடுச்சு, சந்தோஷத்துல."}, {"id": "dir049", "source": "dir", "origin": "e09", "voice": "anitha", "text": "நாங்க ரொம்ப நாளுக்கு அப்புறம் எல்லாரும் ஒண்ணா சேர்ந்தோம்."}, {"id": "dir050", "source": "dir", "origin": "e10", "voice": "arun", "text": "உன்னை பத்தி நான் ரொம்ப பெருமையா நினைக்கிறேன்."}, {"id": "dir051", "source": "dir", "origin": "e11", "voice": "anitha", "text": "அவரு போயிட்டாரு, நேத்து ராத்திரி."}, {"id": "dir052", "source": "dir", "origin": "e12", "voice": "arun", "text": "இந்த வீட்ட விட்டு போகணும்னு நினைச்சாலே கஷ்டமா இருக்கு."}, {"id": "dir053", "source": "dir", "origin": "e13", "voice": "anitha", "text": "எனக்கு இப்ப யாரும் இல்ல."}, {"id": "dir054", "source": "dir", "origin": "e14", "voice": "arun", "text": "அவ என்கிட்ட ஒரு வார்த்தை கூட சொல்லாம போயிட்டா."}, {"id": "dir055", "source": "dir", "origin": "e15", "voice": "anitha", "text": "நான் எவ்ளோ முயற்சி பண்ணாலும் முடியல."}, {"id": "dir056", "source": "dir", "origin": "e16", "voice": "arun", "text": "அந்த நாள்ல திரும்ப போக முடியாது, அது தான் கஷ்டம்."}, {"id": "dir057", "source": "dir", "origin": "e17", "voice": "anitha", "text": "ரொம்ப நாள் கழிச்சு அந்த ஃபோட்டோ பார்த்தேன், மனசு கனமா ஆயிடுச்சு."}, {"id": "dir058", "source": "dir", "origin": "e18", "voice": "arun", "text": "அவங்க என்னை நம்பினாங்க, நான் அதை காப்பாத்தல."}, {"id": "dir059", "source": "dir", "origin": "e19", "voice": "anitha", "text": "எனக்கு இந்த ஊர்ல ஒரு இடமும் இல்லாம போயிடுச்சு."}, {"id": "dir060", "source": "dir", "origin": "e20", "voice": "arun", "text": "நான் தனியா உட்கார்ந்து நெறைய நேரம் யோசிச்சேன்."}, {"id": "dir061", "source": "dir", "origin": "e21", "voice": "anitha", "text": "எத்தன தடவ சொன்னேன், நீ கேட்கவே மாட்டியா?"}, {"id": "dir062", "source": "dir", "origin": "e22", "voice": "arun", "text": "இது எப்படி நடந்ததுன்னு எனக்கு பதில் வேணும், இப்பவே."}, {"id": "dir063", "source": "dir", "origin": "e23", "voice": "anitha", "text": "என் பொறுமைக்கும் ஒரு அளவு இருக்கு."}, {"id": "dir064", "source": "dir", "origin": "e24", "voice": "arun", "text": "நீங்க செஞ்சது ரொம்ப தப்பு, அதை ஏத்துக்கவே மாட்டீங்களா?"}, {"id": "dir065", "source": "dir", "origin": "e25", "voice": "anitha", "text": "இன்னொரு தடவ இப்படி பேசுனா நான் பேசவே மாட்டேன்."}, {"id": "dir066", "source": "dir", "origin": "e26", "voice": "arun", "text": "எனக்கு இதுல எந்த சம்பந்தமும் இல்ல, எதுக்கு என்னை இழுக்குறீங்க?"}, {"id": "dir067", "source": "dir", "origin": "e27", "voice": "anitha", "text": "இந்த மாதிரி ஒரு வேலைய நான் எதிர்பார்க்கவே இல்ல உங்ககிட்ட இருந்து."}, {"id": "dir068", "source": "dir", "origin": "e28", "voice": "arun", "text": "அந்த சத்தம் என்ன? யாரோ உள்ள இருக்காங்க."}, {"id": "dir069", "source": "dir", "origin": "e29", "voice": "anitha", "text": "ஃபோன் எடுக்க மாட்டேங்கறாங்க, எனக்கு பயமா இருக்கு."}, {"id": "dir070", "source": "dir", "origin": "e30", "voice": "arun", "text": "இருட்டுல அந்த வழியா போக எனக்கு தைரியம் இல்ல."}, {"id": "dir071", "source": "dir", "origin": "e31", "voice": "anitha", "text": "ரிப்போர்ட் வர்ற வரைக்கும் எனக்கு தூக்கமே வரல."}, {"id": "dir072", "source": "dir", "origin": "e32", "voice": "arun", "text": "அவன் இன்னும் வீட்டுக்கு வரல, ராத்திரி பதினொன்னு ஆயிடுச்சு."}, {"id": "dir073", "source": "dir", "origin": "e33", "voice": "anitha", "text": "அடடா, நீ எப்ப வந்த? எனக்கு தெரியவே இல்ல!"}, {"id": "dir074", "source": "dir", "origin": "e34", "voice": "arun", "text": "இதை நான் கனவுலயும் நினைக்கல."}, {"id": "dir075", "source": "dir", "origin": "e35", "voice": "anitha", "text": "என்ன? அவரு தான் அதை செஞ்சாரா?"}, {"id": "dir076", "source": "dir", "origin": "e36", "voice": "arun", "text": "இந்த விலைக்கு இது கிடைக்கும்னு நான் நம்பவே இல்ல."}, {"id": "dir077", "source": "dir", "origin": "e37", "voice": "anitha", "text": "இந்த இடத்த பாரு, முழுக்க குப்பையா கிடக்கு."}, {"id": "dir078", "source": "dir", "origin": "e38", "voice": "arun", "text": "அந்த வாசனைய என்னால தாங்க முடியல."}, {"id": "dir079", "source": "dir", "origin": "e39", "voice": "anitha", "text": "இப்படி ஒரு வேலைய யாராவது செய்வாங்களா?"}, {"id": "dir080", "source": "dir", "origin": "e40", "voice": "arun", "text": "அந்த சாப்பாட்ட பார்த்தாலே எனக்கு வேண்டாம்னு ஆகுது."}, {"id": "dir081", "source": "dir", "origin": "e41", "voice": "anitha", "text": "அவங்க நல்லா இருக்காங்கன்னு கேட்டதுல எனக்கு ஒரு நிம்மதி."}, {"id": "dir082", "source": "dir", "origin": "e42", "voice": "arun", "text": "நான் எதிர்பார்த்ததை விட நல்லா நடந்துடுச்சு."}, {"id": "dir083", "source": "dir", "origin": "e43", "voice": "anitha", "text": "அந்த கடிதத்த படிச்சு நான் ரொம்ப நேரம் பேசவே இல்ல."}, {"id": "dir084", "source": "dir", "origin": "e44", "voice": "arun", "text": "இது முடியுமா முடியாதான்னு எனக்கு இன்னும் தெரியல."}, {"id": "dir085", "source": "dir", "origin": "e45", "voice": "anitha", "text": "அவங்க முகத்த பார்த்தா ஒண்ணும் சரியில்லன்னு தெரியுது."}, {"id": "dir086", "source": "dir", "origin": "e46", "voice": "arun", "text": "நான் சொன்னது நடந்துடுச்சு, ஆனா எனக்கு சந்தோஷமா இல்ல."}, {"id": "dir087", "source": "dir", "origin": "e47", "voice": "anitha", "text": "எவ்ளோ நாள் ஆனாலும் இதை நான் மறக்க மாட்டேன்."}, {"id": "dir088", "source": "dir", "origin": "e48", "voice": "arun", "text": "அந்த குழந்தை சிரிச்ச சிரிப்பு இன்னும் என் காதுல இருக்கு."}, {"id": "dir089", "source": "dir", "origin": "e49", "voice": "anitha", "text": "நாங்க கஷ்டப்பட்டோம், ஆனா இன்னைக்கு அதுக்கு பலன் கிடைச்சுடுச்சு."}, {"id": "dir090", "source": "dir", "origin": "e50", "voice": "arun", "text": "இதுக்கு மேல நான் எதுவும் சொல்ல விரும்பல."}, {"id": "dir091", "source": "dir", "origin": "e51", "voice": "anitha", "text": "அவன் என்கிட்ட பொய் சொல்லிட்டான், அது தான் வருத்தம்."}, {"id": "dir092", "source": "dir", "origin": "e52", "voice": "arun", "text": "இந்த முடிவு எடுக்க எனக்கு ரொம்ப நாள் ஆச்சு."}, {"id": "dir093", "source": "dir", "origin": "e53", "voice": "anitha", "text": "அந்த ஊர்ல எல்லாரும் எங்களை நல்லா கவனிச்சுக்கிட்டாங்க."}, {"id": "dir094", "source": "dir", "origin": "e54", "voice": "arun", "text": "இப்ப நினைச்சா சிரிப்பு வருது, அப்ப ரொம்ப பயந்துட்டேன்."}, {"id": "dir095", "source": "dir", "origin": "e55", "voice": "anitha", "text": "எனக்கு அவங்களை பார்க்கணும்னு ரொம்ப ஆசையா இருக்கு."}, {"id": "dir096", "source": "dir", "origin": "e56", "voice": "arun", "text": "அவரு சொன்ன வார்த்தை இன்னும் என் மனசுல இருக்கு."}, {"id": "dir097", "source": "dir", "origin": "e57", "voice": "anitha", "text": "இந்த வருஷம் எங்க குடும்பத்துக்கு ரொம்ப கஷ்டமான வருஷம்."}, {"id": "dir098", "source": "dir", "origin": "e58", "voice": "arun", "text": "நான் அங்க போனப்ப யாருமே இல்ல, வீடு காலியா இருந்துச்சு."}, {"id": "dir099", "source": "dir", "origin": "e59", "voice": "anitha", "text": "அவங்க திரும்ப வருவாங்கன்னு நான் இன்னும் நம்புறேன்."}, {"id": "dir100", "source": "dir", "origin": "e60", "voice": "arun", "text": "இது ஒரு சின்ன விஷயம், ஆனா எனக்கு ரொம்ப முக்கியம்."}, {"id": "cap001", "source": "cap", "origin": "ev01", "voice": "anitha", "text": "ஒரு நிமிடம், நான் யோசித்துச் சொல்கிறேன்."}, {"id": "cap002", "source": "cap", "origin": "ev02", "voice": "arun", "text": "அவர் சொன்னதை கேட்டதும், எனக்கு ஒன்றுமே புரியவில்லை."}, {"id": "cap003", "source": "cap", "origin": "ev03", "voice": "anitha", "text": "நேற்று இரவு முழுக்க வேலை, இன்று காலையிலும் அதே வேலை."}, {"id": "cap004", "source": "cap", "origin": "ev04", "voice": "arun", "text": "படிக்கட்டு ஏறி வந்தேன், மூன்றாவது மாடி வரை."}, {"id": "cap005", "source": "cap", "origin": "ev05", "voice": "anitha", "text": "சரி, இப்போது ஆரம்பிக்கலாம்."}, {"id": "cap006", "source": "cap", "origin": "ev06", "voice": "arun", "text": "அந்த கணக்கை மறுபடியும் பார்த்தேன், எதுவும் சரியாக வரவில்லை."}, {"id": "cap007", "source": "cap", "origin": "ev07", "voice": "anitha", "text": "இந்த வெயிலில் நடந்து வந்தது, ரொம்ப கஷ்டமாக இருந்தது."}, {"id": "cap008", "source": "cap", "origin": "ev08", "voice": "arun", "text": "கதவை திறந்து பார்த்தேன், உள்ளே யாரும் இல்லை."}, {"id": "cap009", "source": "cap", "origin": "ev09", "voice": "anitha", "text": "இதை எப்படி சொல்வது என்றே தெரியவில்லை."}, {"id": "cap010", "source": "cap", "origin": "ev10", "voice": "arun", "text": "மறுபடியும் அதே பிரச்சினை. ஒவ்வொரு மாதமும் இதே கதை."}, {"id": "cap011", "source": "cap", "origin": "ev11", "voice": "anitha", "text": "அவரிடம் எத்தனை முறை சொன்னேன். கேட்பதாக இல்லை."}, {"id": "cap012", "source": "cap", "origin": "ev12", "voice": "arun", "text": "சரி, விட்டுவிடுங்கள். நான் பார்த்துக்கொள்கிறேன்."}, {"id": "cap013", "source": "cap", "origin": "ev13", "voice": "anitha", "text": "பஸ் போய்விட்டது. இன்னும் அரை மணி நேரம் காத்திருக்க வேண்டும்."}, {"id": "cap014", "source": "cap", "origin": "ev14", "voice": "arun", "text": "எல்லாம் முடிந்துவிட்டது. இப்போது பேசி என்ன பயன்."}, {"id": "cap015", "source": "cap", "origin": "ev15", "voice": "anitha", "text": "உங்கள் கவனத்திற்கு ஒரு விஷயம் சொல்ல வேண்டும்."}, {"id": "cap016", "source": "cap", "origin": "ev16", "voice": "arun", "text": "மன்னிக்கவும், நான் ஒன்று கேட்கலாமா?"}, {"id": "cap017", "source": "cap", "origin": "ev17", "voice": "anitha", "text": "அவர் முடிக்கும் வரை காத்திருந்தேன். பிறகு நான் பேசினேன்."}, {"id": "cap018", "source": "cap", "origin": "ev18", "voice": "arun", "text": "இந்த கூட்டத்தை இப்போது தொடங்குகிறோம்."}, {"id": "cap019", "source": "cap", "origin": "ev19", "voice": "anitha", "text": "அவன் சொன்ன கதையை கேட்டு எனக்கு சிரிப்பு அடங்கவில்லை."}, {"id": "cap020", "source": "cap", "origin": "ev20", "voice": "arun", "text": "நான் சாவியை குளிர்சாதனப் பெட்டியில் வைத்திருந்தேன். நம்ப முடியவில்லை."}, {"id": "cap021", "source": "cap", "origin": "ev21", "voice": "anitha", "text": "அதை நினைத்தாலே இப்போதும் சிரிப்பு வருகிறது."}, {"id": "cap022", "source": "cap", "origin": "ev22", "voice": "arun", "text": "அவர் குடையை எடுத்துக்கொண்டு போனார், வெயில் அடித்த நாளில்."}, {"id": "cap023", "source": "cap", "origin": "ev23", "voice": "anitha", "text": "எனக்கு சொல்லத் தெரியவில்லை, ஆனால் முயற்சி செய்கிறேன்."}, {"id": "cap024", "source": "cap", "origin": "ev24", "voice": "arun", "text": "படிக்கட்டு ஏறினேன், கதவை திறந்தேன், உள்ளே யாருமில்லை."}, {"id": "cap025", "source": "cap", "origin": "ev25", "voice": "anitha", "text": "ஒரு நிமிடம். இப்போது சொல்கிறேன்."}, {"id": "cap026", "source": "cap", "origin": "ev26", "voice": "arun", "text": "அந்த செய்தியை கேட்டேன். என்ன சொல்வது. ஒன்றும் தோன்றவில்லை."}, {"id": "cap027", "source": "cap", "origin": "ev27", "voice": "anitha", "text": "காலையில் எழுந்து, குழந்தைகளை பள்ளிக்கு அனுப்பி, கடைக்குப் போய் சாமான் வாங்கி வந்தேன்."}, {"id": "cap028", "source": "cap", "origin": "ev28", "voice": "arun", "text": "அந்த அறையில் மேசை, நாற்காலி, புத்தக அலமாரி, எல்லாம் அப்படியே இருந்தது."}, {"id": "cap029", "source": "cap", "origin": "ev29", "voice": "anitha", "text": "ரயில் நிலையத்தில் இறங்கி, ஆட்டோ பிடித்து, வீட்டுக்கு வந்து சேர்ந்தேன்."}, {"id": "cap030", "source": "cap", "origin": "ev30", "voice": "arun", "text": "அவர் பேசிக்கொண்டே இருந்தார், நான் கேட்டுக்கொண்டே இருந்தேன், நேரம் போனதே தெரியவில்லை."}, {"id": "cap031", "source": "cap", "origin": "ev31", "voice": "anitha", "text": "மின்சாரம் இல்லை, தண்ணீர் இல்லை, யாரிடம் சென்று சொல்வது."}, {"id": "cap032", "source": "cap", "origin": "ev32", "voice": "arun", "text": "நான்கு மாடி ஏறி வந்தேன், மூச்சு வாங்குகிறது, ஒரு நிமிடம் உட்காரலாமா?"}, {"id": "cap033", "source": "cap", "origin": "ev33", "voice": "anitha", "text": "நீண்ட நாட்களுக்குப் பிறகு உங்களை பார்க்கிறேன்."}, {"id": "cap034", "source": "cap", "origin": "ev34", "voice": "arun", "text": "வேலை முடிந்தது. இப்போது கொஞ்சம் நிம்மதி."}, {"id": "cap035", "source": "cap", "origin": "ev35", "voice": "anitha", "text": "ஒவ்வொரு நாளும் இதே போராட்டம் தான்."}, {"id": "cap036", "source": "cap", "origin": "ev36", "voice": "arun", "text": "அவள் அழுதுகொண்டே சொன்னாள், நான் ஒன்றும் பேசவில்லை."}, {"id": "cap037", "source": "cap", "origin": "fl01", "voice": "anitha", "text": "அதாவது... எனக்கு சரியாக தெரியவில்லை."}, {"id": "cap038", "source": "cap", "origin": "fl02", "voice": "arun", "text": "உம்... ஒரு நிமிடம், யோசிக்கிறேன்."}, {"id": "cap039", "source": "cap", "origin": "fl03", "voice": "anitha", "text": "என்ன சொல்ல வருகிறேன் என்றால், இது அவ்வளவு எளிதல்ல."}, {"id": "cap040", "source": "cap", "origin": "fl04", "voice": "arun", "text": "அது... அது வேறு விஷயம், அதை பிறகு பேசலாம்."}, {"id": "cap041", "source": "cap", "origin": "fl05", "voice": "anitha", "text": "இல்லை இல்லை, நான் சொன்னது அதை அல்ல."}, {"id": "cap042", "source": "cap", "origin": "fl06", "voice": "arun", "text": "ஆமாம், ஆமாம்... இல்லை, பொறுங்கள். எனக்கு நினைவில்லை."}, {"id": "cap043", "source": "cap", "origin": "fl07", "voice": "anitha", "text": "எப்படி சொல்வது... ஒரு வகையில் சரி, ஒரு வகையில் தவறு."}, {"id": "cap044", "source": "cap", "origin": "fl08", "voice": "arun", "text": "அவர் பெயர்... அவர் பெயர் என்ன... ராமன், ஆமாம் ராமன்."}, {"id": "cap045", "source": "cap", "origin": "fl09", "voice": "anitha", "text": "உம், அப்படியா? எனக்கு இது தெரியாது."}, {"id": "cap046", "source": "cap", "origin": "fl10", "voice": "arun", "text": "நான்... நான் நினைத்தேன் நீங்கள் வரமாட்டீர்கள் என்று."}, {"id": "cap047", "source": "cap", "origin": "fl11", "voice": "anitha", "text": "சரி, அதாவது, நாளை பார்க்கலாம், இல்லையா?"}, {"id": "cap048", "source": "cap", "origin": "fl12", "voice": "arun", "text": "எனக்கு... எனக்கு ஒன்றும் சொல்லத் தோன்றவில்லை."}, {"id": "cap049", "source": "cap", "origin": "fl13", "voice": "anitha", "text": "அது ஒரு... எப்படி சொல்வது... பழைய கட்டிடம்."}, {"id": "cap050", "source": "cap", "origin": "fl14", "voice": "arun", "text": "ஒண்ணு, ரெண்டு... இல்லை, மூன்று பேர் வந்தார்கள்."}, {"id": "cap051", "source": "cap", "origin": "fl15", "voice": "anitha", "text": "நீங்கள் சொல்வது... ஆமாம், புரிகிறது, புரிகிறது."}, {"id": "cap052", "source": "cap", "origin": "fl16", "voice": "arun", "text": "இந்த... இந்த காகிதத்தை எங்கே வைத்தேன்?"}, {"id": "cap053", "source": "cap", "origin": "fl17", "voice": "anitha", "text": "அதாவது, அவர் வரவில்லை, அதனால் நாங்கள் காத்திருந்தோம்."}, {"id": "cap054", "source": "cap", "origin": "fl18", "voice": "arun", "text": "உம்... சரி. நான் பிறகு கூப்பிடுகிறேன்."}, {"id": "cap055", "source": "cap", "origin": "fl19", "voice": "anitha", "text": "எனக்கு தெரிந்தது என்னவென்றால்... இல்லை, அது முக்கியமில்லை."}, {"id": "cap056", "source": "cap", "origin": "fl20", "voice": "arun", "text": "அவங்க... அவங்க நேற்று தான் வந்தாங்க."}, {"id": "cap057", "source": "cap", "origin": "fl21", "voice": "anitha", "text": "ஒரு வேளை... இல்லை, நிச்சயமாக அப்படி இல்லை."}, {"id": "cap058", "source": "cap", "origin": "fl22", "voice": "arun", "text": "இதை... இதை நான் எப்படி விளக்குவது?"}, {"id": "cap059", "source": "cap", "origin": "fl23", "voice": "anitha", "text": "சரி சரி, அதாவது நாளை காலை பத்து மணி, அப்படித்தானே?"}, {"id": "cap060", "source": "cap", "origin": "fl24", "voice": "arun", "text": "நான் நினைக்கிறேன்... ஆமாம், அதுவே சரி."}, {"id": "cap061", "source": "cap", "origin": "cl01", "voice": "anitha", "text": "தமிழ்நாட்டின் தலைநகரம் சென்னை."}, {"id": "cap062", "source": "cap", "origin": "cl02", "voice": "arun", "text": "இந்த புத்தகம் மேசையின் மேல் உள்ளது."}, {"id": "cap063", "source": "cap", "origin": "cl03", "voice": "anitha", "text": "காவிரி ஆறு தமிழ்நாட்டின் முக்கிய நதி."}, {"id": "cap064", "source": "cap", "origin": "cl04", "voice": "arun", "text": "அரசு அறிவிப்பு நாளை வெளியிடப்படும்."}, {"id": "cap065", "source": "cap", "origin": "cl05", "voice": "anitha", "text": "ரயில் காலை ஆறு மணிக்கு புறப்படுகிறது."}, {"id": "cap066", "source": "cap", "origin": "cl06", "voice": "arun", "text": "நூலகம் திங்கள் முதல் வெள்ளி வரை திறந்திருக்கும்."}, {"id": "cap067", "source": "cap", "origin": "cl07", "voice": "anitha", "text": "மாநிலத்தின் மொத்த மக்கள் தொகை ஏழு கோடி."}, {"id": "cap068", "source": "cap", "origin": "cl08", "voice": "arun", "text": "இந்த அறைக்கு இரண்டு ஜன்னல்கள் உள்ளன."}, {"id": "cap069", "source": "cap", "origin": "cl09", "voice": "anitha", "text": "கல்லூரி வளாகம் நகரின் தெற்கே அமைந்துள்ளது."}, {"id": "cap070", "source": "cap", "origin": "cl10", "voice": "arun", "text": "மருத்துவமனை இருபத்து நான்கு மணி நேரமும் செயல்படுகிறது."}, {"id": "cap071", "source": "cap", "origin": "cl11", "voice": "anitha", "text": "விண்ணப்பத்தை இணையதளத்தில் பூர்த்தி செய்யவும்."}, {"id": "cap072", "source": "cap", "origin": "cl12", "voice": "arun", "text": "கூட்டம் மாநாட்டு அரங்கில் நடைபெறும்."}, {"id": "cap073", "source": "cap", "origin": "cl13", "voice": "anitha", "text": "பாடத்திட்டம் மூன்று பகுதிகளாக பிரிக்கப்பட்டுள்ளது."}, {"id": "cap074", "source": "cap", "origin": "cl14", "voice": "arun", "text": "கடற்கரை சாலை நேற்று முதல் மூடப்பட்டுள்ளது."}, {"id": "cap075", "source": "cap", "origin": "cl15", "voice": "anitha", "text": "இந்த திட்டம் ஐந்து ஆண்டுகளில் முடிக்கப்படும்."}, {"id": "cap076", "source": "cap", "origin": "cl16", "voice": "arun", "text": "மாணவர்கள் தேர்வு அறைக்கு சரியான நேரத்தில் வர வேண்டும்."}, {"id": "cap077", "source": "cap", "origin": "cl17", "voice": "anitha", "text": "நகரின் வெப்பநிலை முப்பத்து இரண்டு டிகிரி."}, {"id": "cap078", "source": "cap", "origin": "cl18", "voice": "arun", "text": "அந்த கோவில் பதினோராம் நூற்றாண்டில் கட்டப்பட்டது."}, {"id": "cap079", "source": "cap", "origin": "cl19", "voice": "anitha", "text": "தபால் நிலையம் சந்தைக்கு அருகில் உள்ளது."}, {"id": "cap080", "source": "cap", "origin": "cl20", "voice": "arun", "text": "விமானம் மதியம் ஒரு மணிக்கு வந்து சேரும்."}, {"id": "cap081", "source": "cap", "origin": "cl21", "voice": "anitha", "text": "இந்த வகுப்பில் முப்பது மாணவர்கள் உள்ளனர்."}, {"id": "cap082", "source": "cap", "origin": "cl22", "voice": "arun", "text": "அறிக்கை அடுத்த வாரம் சமர்ப்பிக்கப்படும்."}, {"id": "cap083", "source": "cap", "origin": "cl23", "voice": "anitha", "text": "பூங்கா காலை ஐந்து மணிக்கு திறக்கப்படுகிறது."}, {"id": "cap084", "source": "cap", "origin": "cl24", "voice": "arun", "text": "தண்ணீர் விநியோகம் மாலை நான்கு மணி வரை இருக்கும்."}]''')

PAYLOAD = {
 "worker.py": ""
}


def log(message: str) -> None:
    print(message, flush=True)


def _directories(root: Path, depth: int = 0):
    if not root.exists() or depth > _MAX_MOUNT_DEPTH:
        return
    for entry in sorted(root.iterdir()):
        if entry.is_dir():
            yield entry
            yield from _directories(entry, depth + 1)


def find_dataset(*markers: str) -> Path:
    for mount in sorted(_directories(Path("/kaggle/input"))):
        if all((mount / marker).exists() for marker in markers):
            return mount
    raise SystemExit(f"could not find a mount containing {markers}")


def main() -> int:
    result = subprocess.run([sys.executable, "-m", "pip", "uninstall", "-y", "torchao"],
                            capture_output=True, text=True)
    log(f"pip uninstall torchao -> {result.returncode}")
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", "snac==1.2.1",
                    "onnxruntime==1.20.1", "soundfile==0.14.0", "sentencepiece"], check=True)
    import torch
    from huggingface_hub import snapshot_download

    gpus = torch.cuda.device_count()
    log(f"group {GROUP}: {SYSTEMS}; {len(PROMPTS)} prompts; {gpus} GPU(s): "
        f"{[torch.cuda.get_device_name(i) for i in range(gpus)]}")
    if not gpus:
        raise SystemExit("no GPU in this session")

    token = (find_dataset("hf_read_token.txt") / "hf_read_token.txt").read_text(
        encoding="utf-8").strip()
    source = find_dataset("scoring", "text", "eval")
    package = Path("/kaggle/tmp/pkg/geetha")
    package.mkdir(parents=True, exist_ok=True)
    shutil.copytree(source, package, dirs_exist_ok=True)

    spec_common = {
        "prompts": PROMPTS, "seed": SEED, "out_dir": str(OUT_DIR),
        "package_parent": str(package.parent),
        "conformer_dir": snapshot_download(CONFORMER_ID, revision=CONFORMER_REVISION,
                                           token=token),
        "transcribe_dir": snapshot_download(TRANSCRIBE_ID, revision=TRANSCRIBE_REVISION,
                                            token=token),
        "snac_id": SNAC_ID, "snac_revision": SNAC_REVISION,
        "revisions": {CONFORMER_ID: CONFORMER_REVISION, TRANSCRIBE_ID: TRANSCRIBE_REVISION},
    }
    work = Path("/kaggle/tmp/bench")
    work.mkdir(parents=True, exist_ok=True)
    release = work / "release"
    release.mkdir(exist_ok=True)
    for name, encoded in PAYLOAD.items():
        target = work / name if name == "worker.py" else release / name
        target.write_bytes(base64.b64decode(encoded))
        log(f"  unpacked {name}: {target.stat().st_size:,} bytes  "
            f"sha256 {hashlib.sha256(target.read_bytes()).hexdigest()[:16]}")

    if GROUP == "ours":
        base_dir = snapshot_download(MODEL_ID, revision=BASE_REVISION, token=token)
        ckpt = Path(snapshot_download(CKPT_REPO, token=token,
                                      allow_patterns=[f"{ADAPTER}/*"]))
        adapter_dir = ckpt / ADAPTER
        if not (adapter_dir / "adapter_config.json").exists():
            adapter_dir = sorted(adapter_dir.rglob("adapter_config.json"))[0].parent
        spec_common.update(base_dir=base_dir, adapter_dir=str(adapter_dir),
                           release_dir=str(release))
        spec_common["revisions"].update({MODEL_ID: BASE_REVISION, "geetha_adapter": ADAPTER})
    token = ""
    del token
    for name in ("HF_TOKEN", "HUGGING_FACE_HUB_TOKEN"):
        os.environ.pop(name, None)
    if GROUP == "rivals":
        # Public models: fetched without the token, at pinned commits, and only the
        # files inference needs (no server, training or demo scripts).
        rumik_dir = snapshot_download(
            RUMIK_ID, revision=RUMIK_REVISION, token=False,
            allow_patterns=["*.json", "*.safetensors", "codec/*", *RUMIK_CODE_SHA256])
        snor_dir = snapshot_download(SNOR_ID, revision=SNOR_REVISION, token=False,
                                     allow_patterns=["*.json", "*.safetensors", "*.jinja"])
        for name, expected in RUMIK_CODE_SHA256.items():
            found = hashlib.sha256((Path(rumik_dir) / name).read_bytes()).hexdigest()
            if found != expected:
                raise SystemExit(f"{name} is not the file that was reviewed: {found}")
        extra = sorted(p.name for p in Path(rumik_dir).rglob("*.py")
                       if p.name not in RUMIK_CODE_SHA256)
        if extra:
            raise SystemExit(f"unreviewed Python in the Rumik snapshot: {extra}")
        spec_common.update(rumik_dir=rumik_dir, snor_dir=snor_dir)
        spec_common["revisions"].update({RUMIK_ID: RUMIK_REVISION, SNOR_ID: SNOR_REVISION,
                                         SNAC_ID: SNAC_REVISION})
    snapshot_download(SNAC_ID, revision=SNAC_REVISION, token=False)
    log(f"revisions: {spec_common['revisions']}")

    logs = OUT_DIR / "logs"
    logs.mkdir(parents=True, exist_ok=True)
    parallel = gpus >= len(SYSTEMS)
    budget = RENDER_BUDGET_PARALLEL_S if parallel else RENDER_BUDGET_SERIAL_S
    started = time.time()

    def launch(system: str, gpu: int) -> subprocess.Popen:
        spec_path = work / f"spec_{system}.json"
        spec_path.write_text(json.dumps({**spec_common, "system": system,
                                         "render_budget_s": budget}, ensure_ascii=False),
                             encoding="utf-8")
        env = {k: v for k, v in os.environ.items()
               if k not in ("HF_TOKEN", "HUGGING_FACE_HUB_TOKEN")}
        env.update(CUDA_VISIBLE_DEVICES=str(gpu), PYTHONUNBUFFERED="1",
                   PYTHONIOENCODING="utf-8", TOKENIZERS_PARALLELISM="false")
        process = subprocess.Popen(
            [sys.executable, str(work / "worker.py"), str(spec_path)], env=env,
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
            encoding="utf-8", errors="replace")

        def relay() -> None:
            with open(logs / f"{system}.log", "w", encoding="utf-8") as sink:
                for line in process.stdout:
                    sink.write(line)
                    sink.flush()
                    if line.startswith(f"[{system}]"):
                        log(line.rstrip())

        thread = threading.Thread(target=relay, daemon=True)
        thread.start()
        process.relay = thread            # type: ignore[attr-defined]
        log(f"started {system} on GPU {gpu} (render budget {budget / 3600:.1f} h)")
        return process

    def finish(system: str, process: subprocess.Popen) -> None:
        code = process.wait()
        process.relay.join(timeout=30)    # type: ignore[attr-defined]
        log(f"{system} exited {code} after {time.time() - started:.0f} s")
        if code:
            tail = (logs / f"{system}.log").read_text(encoding="utf-8").splitlines()[-40:]
            log("\n".join(f"    {line}" for line in tail))

    if parallel:
        running = [(system, launch(system, gpu)) for gpu, system in enumerate(SYSTEMS)]
        for system, process in running:
            finish(system, process)
    else:
        for system in SYSTEMS:
            finish(system, launch(system, 0))

    log("")
    log("=== summary (CER is scored on the PC from these transcripts) ===")
    for system in SYSTEMS:
        path = OUT_DIR / f"bench_{system}.json"
        if not path.exists():
            log(f"  {system}: NO RESULT FILE")
            continue
        report = json.loads(path.read_text(encoding="utf-8"))
        clips = report["clips"]
        good = sum(1 for c in clips.values() if c["valid"])
        skipped = sum(1 for c in clips.values() if c["reason"] == "not_run")
        log(f"  {system}: valid {good}/{len(clips)}  not run {skipped}  transcripts "
            f"{ {j: len(h) for j, h in report['hypotheses'].items()} }  "
            f"finished {report.get('finished', False)}  failure {report.get('failure')}")
    log(f"wrote results in {time.time() - started:.0f} s")
    return 0


if __name__ == "__main__":
    sys.exit(main())
